<template><div><Select :value="value||''" :disabled="disabled" filterable remote :remote-method="search" :loading="loading" clearable :placeholder="placeholder||'输入名称搜索'" @on-change="select" @on-open-change="opened"><Option v-for="item in options" :key="item.id" :value="item.id" :label="item.path||item.name||item.displayName||item.id"><span>{{item.path||item.name||item.displayName||'名称未提供'}}</span><span class="ui-meta"> · {{item.status?status(item.status):item.enabled===false?'停用':'编号'}} · {{item.number||item.id}}<template v-if="item.revision"> · v{{item.revision}}</template></span></Option></Select><div v-if="total>size" class="ui-meta"><Button size="small" :disabled="loading||page<=1" @click="move(-1)">上一页</Button><span> {{page}} / {{Math.ceil(total/size)}} </span><Button size="small" :disabled="loading||page*size>=total" @click="move(1)">下一页</Button></div><p v-if="error" class="ui-error">{{error}} <button type="button" class="ui-link" @click="fetch">重试</button></p></div></template>
<script>import {uiRead} from '@/api/stage1-usability';import {managerSession} from '@/libs/manager-session';import {status} from '../display.cjs';export default {props:{loader:Function,value:String,type:{type:String,required:true},params:{type:Object,default:()=>({})},disabled:Boolean,placeholder:String},data:()=>({options:[],chosen:null,page:1,size:20,total:0,q:'',loading:false,error:'',ticket:0,timer:null}),watch:{value:{immediate:true,handler(){this.resolveSelected();}},params:{deep:true,handler(next,previous){if(JSON.stringify(next)===JSON.stringify(previous))return;this.ticket++;this.options=[];this.chosen=null;this.page=1;this.resolveSelected();}}},beforeDestroy(){this.ticket++;clearTimeout(this.timer);},methods:{status,loadOptions(params){return this.loader?this.loader(params):uiRead('/lookups/'+this.type,params);},opened(open){if(open&&!this.options.length)this.fetch();},search(value){clearTimeout(this.timer);this.q=value;this.page=1;this.timer=setTimeout(()=>this.fetch(),220);},move(delta){this.page+=delta;this.fetch();},async resolveSelected(){if(!this.value){this.chosen=null;this.$emit('selected',null);return;}const id=this.value,parameters=JSON.stringify(this.params),source=managerSession.snapshot();try{const v=await this.loadOptions({...this.params,selected:id,pageSize:1});if(this.value!==id||parameters!==JSON.stringify(this.params)||!managerSession.sameSession(source))return;this.chosen=v.records[0]||{id,name:'名称未提供（原引用）'};this.merge();this.$emit('selected',this.chosen);}catch(e){if(this.value===id&&parameters===JSON.stringify(this.params)&&managerSession.sameSession(source)){this.chosen={id,name:'原引用不可读'};this.error=e.message;this.merge();}}},merge(rows=[]){this.options=[...(this.chosen?[this.chosen]:[]),...rows.filter(r=>!this.chosen||r.id!==this.chosen.id)];},async fetch(){const ticket=++this.ticket,source=managerSession.snapshot();this.loading=true;this.error='';try{const v=await this.loadOptions({...this.params,q:this.q||undefined,pageNumber:this.page,pageSize:this.size});if(ticket!==this.ticket||!managerSession.sameSession(source))return;this.total=v.total;this.merge(v.records);}catch(e){if(ticket===this.ticket){this.error=e.message;this.options=this.chosen?[this.chosen]:[];this.total=0;}}finally{if(ticket===this.ticket)this.loading=false;}},select(id){this.chosen=this.options.find(x=>x.id===id)||null;this.$emit('input',id||'');this.$emit('selected',this.chosen);}}};</script>
